package dev.enro.controller

import dev.enro.EnroController
import dev.enro.annotations.InternalEnroApi
import dev.enro.platform.platformNavigationModule

/**
 * Creates the [EnroController] for a generated `installNavigationController` function.
 * Called by code generated by enro-processor; the name and signature must stay stable
 * so that already-generated code keeps linking.
 */
@InternalEnroApi
public fun internalCreateEnroController(
    isDebug: Boolean = false,
    builder: NavigationModule.BuilderScope.() -> Unit = {},
) : EnroController {
    val module = createNavigationModule(builder)
    return EnroController().apply {
        this.isDebug = isDebug
        addModule(defaultNavigationModule)
        addModule(platformNavigationModule)
        addModule(module)
    }
}